{
  "name": "apm_update_basic_rate",
  "confidence": "medium",
  "docstring": "Updates an APM/802.11 target record from basic-rate parameters in a received entry and dispatches the corresponding event.",
  "subsystem": "mac",
  "var_renames": {
    "a2": "param",
    "v7": "entry_id",
    "v9": "target_record"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "source param entry id (*param)"
    },
    {
      "offset": 2,
      "meaning": "source param basic_rates byte (low byte of first copied uint32)"
    },
    {
      "offset": 6,
      "meaning": "source param second copied uint32"
    },
    {
      "offset": 10,
      "meaning": "source param third copied uint32"
    },
    {
      "offset": 14,
      "meaning": "source param byte copied to target+204"
    },
    {
      "offset": 192,
      "meaning": "target word receiving first param word/basic-rate vector"
    },
    {
      "offset": 196,
      "meaning": "target word receiving second param word"
    },
    {
      "offset": 200,
      "meaning": "target word receiving third param word"
    },
    {
      "offset": 204,
      "meaning": "target byte receiving source param byte"
    },
    {
      "offset": 106,
      "meaning": "entry selector/type byte; value 2 selects this copy/update path"
    }
  ]
}
